"use client";

import { useEffect, useRef } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

export function ScrollProgress() {
  const progressRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const element = progressRef.current;

    if (!element) return;

    const setProgress = gsap.quickSetter(element, "scaleX");

    const trigger = ScrollTrigger.create({
      start: 0,
      end: "max",
      invalidateOnRefresh: true,
      onUpdate: ({ progress }) => {
        setProgress(progress);
        element.setAttribute("aria-valuenow", String(Math.round(progress * 100)));
      },
    });

    return () => trigger.kill();
  }, []);

  return (
    <div
      className="pointer-events-none fixed inset-x-0 top-0 z-[100] h-1 bg-black/10"
      aria-hidden="true"
    >
      <div
        ref={progressRef}
        role="progressbar"
        aria-label="Progreso de lectura"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={0}
        className="h-full w-full origin-left scale-x-0 bg-lime-400 will-change-transform"
      />
    </div>
  );
}
